css:
.local-document .rmd-cattca {
  --rmd-cattca-height: 420px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 16px 0;
  padding: 16px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-panel, 12px);
  box-shadow: var(--shadow-sm);
  font-family: var(--font-sans);
}

.local-document .rmd-cattca-head {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
  justify-content: space-between;
}

.local-document .rmd-cattca-heading {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: baseline;
  min-width: 0;
}

.local-document .rmd-cattca-title {
  font-size: 1rem;
  font-weight: 650;
  letter-spacing: 0.01em;
}

.local-document .rmd-cattca-status {
  color: var(--ink-muted);
  font-size: 0.8rem;
}

.local-document .rmd-cattca-action,
.local-document .rmd-cattca-choice,
.local-document .rmd-cattca-submit {
  min-height: 44px;
  padding: 9px 14px;
  color: var(--ink);
  background: var(--surface-subtle);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-control, 8px);
  font: inherit;
  line-height: 1.4;
  cursor: pointer;
}

.local-document .rmd-cattca-action:hover,
.local-document .rmd-cattca-choice:hover,
.local-document .rmd-cattca-submit:hover {
  background: var(--surface-hover);
}

.local-document .rmd-cattca-action:focus-visible,
.local-document .rmd-cattca-choice:focus-visible,
.local-document .rmd-cattca-submit:focus-visible,
.local-document .rmd-cattca-input:focus-visible {
  outline: 2px solid var(--focus-outline, var(--accent));
  outline-offset: 2px;
}

.local-document .rmd-cattca-action:disabled,
.local-document .rmd-cattca-choice:disabled,
.local-document .rmd-cattca-submit:disabled,
.local-document .rmd-cattca-input:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.local-document .rmd-cattca-transcript {
  min-height: 160px;
  max-height: var(--rmd-cattca-height);
  padding: 14px 16px;
  overflow: auto;
  background: var(--surface-subtle);
  border: 1px solid var(--line);
  border-radius: var(--radius-card, 10px);
  line-height: 1.8;
  overscroll-behavior: contain;
}

.local-document .rmd-cattca-line {
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.local-document .rmd-cattca-line + .rmd-cattca-line {
  margin-top: 2px;
}

.local-document .rmd-cattca-line[data-cattca-line='value'] {
  color: var(--accent-text, var(--accent));
  font-weight: 600;
}

.local-document .rmd-cattca-choices {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.local-document .rmd-cattca-choice {
  width: 100%;
  text-align: start;
}

.local-document .rmd-cattca-choice::before {
  content: '›';
  margin-inline-end: 8px;
  color: var(--accent-text, var(--accent));
}

.local-document .rmd-cattca-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.local-document .rmd-cattca-label {
  color: var(--ink-muted);
  font-size: 0.86rem;
}

.local-document .rmd-cattca-input {
  min-height: 44px;
  padding: 8px 12px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-field, 8px);
  font: inherit;
}

.local-document .rmd-cattca-input-row {
  display: flex;
  gap: 8px;
}

.local-document .rmd-cattca-input-row .rmd-cattca-input {
  flex: 1 1 auto;
  min-width: 0;
}

.local-document .rmd-cattca-error {
  margin: 0;
  padding: 10px 12px;
  color: var(--danger);
  background: var(--danger-soft);
  border: 1px solid var(--danger-line);
  border-radius: var(--radius-control, 8px);
}

.local-document .rmd-cattca-end {
  margin: 0;
  color: var(--ink-muted);
  font-size: 0.86rem;
  text-align: end;
}

.local-document .rmd-cattca-debug {
  padding: 10px 12px;
  background: var(--code-bg, var(--surface-subtle));
  border: 1px solid var(--line);
  border-radius: var(--radius-control, 8px);
  font-family: var(--font-mono);
  font-size: 0.8rem;
}

.local-document .rmd-cattca-debug summary {
  cursor: pointer;
  font-weight: 600;
}

.local-document .rmd-cattca-debug dl {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 4px 12px;
  margin: 8px 0 0;
}

.local-document .rmd-cattca-debug dl div {
  display: contents;
}

.local-document .rmd-cattca-debug dt {
  color: var(--ink-muted);
}

.local-document .rmd-cattca-debug dd {
  margin: 0;
  overflow-wrap: anywhere;
}

.local-document .rmd-cattca-debug ol {
  margin: 8px 0 0;
  padding-inline-start: 20px;
}

.local-document .rmd-cattca-debug li {
  margin: 2px 0;
  overflow-wrap: anywhere;
}

@media (max-width: 520px) {
  .local-document .rmd-cattca {
    padding: 12px;
  }

  .local-document .rmd-cattca-input-row {
    flex-direction: column;
  }
}
